package com.jarvis.ai;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.net.*;import android.provider.Settings;import android.speech.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.camera.view.PreviewView;import java.util.*;
public class MainActivity extends AppCompatActivity{
 TextView chat,status,mode,connection,hud;EditText input;MemoryStore memory;NotificationStore notes;AIClient ai;LanguageManager voice;OfflineEngine offline;ToolRegistry tools;SecureStore secure;CameraXVisionController vision;boolean cameraOn=false;boolean authenticated=false;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);chat=findViewById(R.id.chat);status=findViewById(R.id.status);mode=findViewById(R.id.mode);connection=findViewById(R.id.connection);hud=findViewById(R.id.hud);input=findViewById(R.id.input);memory=new MemoryStore(this);notes=new NotificationStore(this);ai=new AIClient();voice=new LanguageManager(this);offline=new OfflineEngine(this);tools=new ToolRegistry();secure=new SecureStore(this);vision=new CameraXVisionController(this,(PreviewView)findViewById(R.id.preview));
 ai.configure(secure.get("endpoint","https://api.openai.com/v1/chat/completions"),secure.get("key",""),secure.get("model","gpt-4o-mini"));findViewById(R.id.send).setOnClickListener(v->send());findViewById(R.id.voice).setOnClickListener(v->listenOnce());findViewById(R.id.camera).setOnClickListener(v->toggleCamera());findViewById(R.id.memory).setOnClickListener(v->show("حافظه بلندمدت",memory.recent(50)));findViewById(R.id.notifications).setOnClickListener(v->notificationMenu());findViewById(R.id.wake).setOnClickListener(v->toggleWake());findViewById(R.id.menu).setOnClickListener(this::menu);
 status.setText("● "+(isOnline()?"متصل":"آفلاین"));connection.setText((isOnline()?"AI: ●":"AI: ○")+"  Offline: ●");mode.setText("حالت: هوشمند • زبان: فارسی • صدا: فارسی");hud.setText("◉ CORE / READY • VISION / STANDBY • MEMORY / READY");append("جارویس","سلام! من جارویس 1.021 هستم. حالت پیش‌فرض فارسی است.");if(!secure.get("activated","").equals("1"))new Handler().postDelayed(()->passwordGate(),400);}
 boolean isOnline(){return ((android.net.ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE)).getActiveNetwork()!=null;}
 void send(){String q=input.getText().toString().trim();if(q.isEmpty())return;input.setText("");append("شما",q);memory.add("user",q);String local=offline.answer(q);if(local!=null){respond(local);return;}String l=q.toLowerCase(Locale.ROOT);if(l.startsWith("باز کن ")||l.startsWith("open ")||l.startsWith("اجرا ")||l.startsWith("do ")){String a=q.replaceFirst("(?i)^(باز کن|open|اجرا|do)\\s*","");respond(tools.execute(this,a));return;}if(l.contains("پاسخ پیام")||l.contains("reply message")){confirmReply();return;}ai.ask("تو JARVIS هستی. زبان پیش‌فرض فارسی است. همیشه تا وقتی کاربر زبان را تغییر نداده، فقط فارسی پاسخ بده. پاسخ طبیعی و کوتاه بده. کاربر: "+q+"\nحافظه:\n"+memory.recent(16),this::respond);}
 void respond(String s){append("جارویس",s);memory.add("assistant",s);voice.speak(s,.95f);}
 void listenOnce(){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},8);return;}Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"fa-IR").putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true);startActivityForResult(i,99);}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==99&&c==RESULT_OK&&d!=null){ArrayList<String>x=d.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(x!=null&&!x.isEmpty()){input.setText(x.get(0));send();}}}
 void toggleCamera(){if(checkSelfPermission(android.Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.CAMERA},42);return;}cameraOn=!cameraOn;findViewById(R.id.preview).setVisibility(cameraOn?View.VISIBLE:View.GONE);findViewById(R.id.cameraDim).setVisibility(cameraOn?View.VISIBLE:View.GONE);if(cameraOn){vision.start();findViewById(R.id.camera).setOnClickListener(v->vision.shot(ai,this::respond));hud.setText("◉ VISION / LIVE • دوربین فعال • برای تحلیل دوباره بزن");}else{vision.stop();findViewById(R.id.camera).setOnClickListener(v->toggleCamera());hud.setText("◉ CORE / READY • VISION / STANDBY");}}
 void toggleWake(){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},8);return;}startService(new Intent(this,JarvisVoiceService.class));status.setText("● Wake word فعال • Hey JARVIS");respond("گوش‌به‌زنگ شدم. می‌توانی بگویی Hey JARVIS.");}
 void menu(View v){PopupMenu p=new PopupMenu(this,v);p.getMenu().add("حالت پشت‌صحنه");p.getMenu().add("زبان اصلی: فارسی");p.getMenu().add("زبان ویس: فارسی");p.getMenu().add("زبان نوشته: فارسی");p.getMenu().add("تنظیمات هوش مصنوعی");p.getMenu().add("مجوزهای Android");p.getMenu().add("درباره JARVIS 1.021");p.setOnMenuItemClickListener(i->{String s=i.getTitle().toString();if(s.contains("تنظیمات"))setupAI();else if(s.contains("مجوز"))startActivity(new Intent(Settings.ACTION_SETTINGS));else if(s.contains("زبان"))respond("زبان پیش‌فرض فارسی است و تا وقتی تغییرش ندهی فارسی باقی می‌ماند.");else if(s.contains("پشت"))show("حالت پشت‌صحنه","ویس، اعلان‌ها، حافظه و Wake Word می‌توانند با سرویس‌های مجاز Android در پس‌زمینه فعال باشند.");else show("JARVIS 1.021","هسته فارسی • Offline Engine • Vision • Tools • Memory • Secure Key Store");return true;});p.show();}
 void notificationMenu(){new AlertDialog.Builder(this).setTitle("پیام‌های دریافتی").setMessage(notes.briefing()).setPositiveButton("تأیید پاسخ به آخرین پیام",(d,w)->confirmReply()).setNeutralButton("باز کردن دسترسی اعلان‌ها",(d,w)->startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"))).setNegativeButton("بستن",null).show();}
 void confirmReply(){new AlertDialog.Builder(this).setTitle("تأیید ارسال").setMessage("می‌خواهی جارویس به آخرین پیام ذخیره‌شده پاسخ پیشنهادی بفرستد؟").setPositiveButton("بله، ارسال کن",(d,w)->{String s=NotificationAction.replyLatest(this,"حتماً، جارویس پاسخ می‌دهد.");respond("پاسخ ارسال شد: "+s);}).setNegativeButton("لغو",null).show();}
 void setupAI(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText e=new EditText(this);e.setHint("Endpoint");e.setText(secure.get("endpoint","https://api.openai.com/v1/chat/completions"));EditText k=new EditText(this);k.setHint("API Key");k.setText(secure.get("key",""));k.setInputType(129);EditText m=new EditText(this);m.setHint("Model");m.setText(secure.get("model","gpt-4o-mini"));l.addView(e);l.addView(k);l.addView(m);new AlertDialog.Builder(this).setTitle("تنظیمات AI").setMessage("کلید API در فضای رمزنگاری‌شده Android نگهداری می‌شود.").setView(l).setPositiveButton("ذخیره",(d,w)->{secure.put("endpoint",e.getText().toString());secure.put("key",k.getText().toString());secure.put("model",m.getText().toString());ai.configure(e.getText().toString(),k.getText().toString(),m.getText().toString());respond("تنظیمات با موفقیت ذخیره شد.");}).setNegativeButton("لغو",null).show();}
 void passwordGate(){EditText e=new EditText(this);e.setInputType(129);e.setHint("رمز JARVIS");new AlertDialog.Builder(this).setTitle("فعال‌سازی JARVIS").setMessage("برای فعال‌سازی اولیه رمز را وارد کن.").setView(e).setCancelable(false).setPositiveButton("فعال‌سازی",(d,w)->{if("ayhan2012".equals(e.getText().toString())){secure.put("activated","1");respond("فعال‌سازی موفق بود.");}else{Toast.makeText(this,"رمز نادرست است.",Toast.LENGTH_LONG).show();new Handler().postDelayed(this::passwordGate,300);}}).show();}
 void append(String a,String b){chat.append("\n"+a+"  ›  "+b+"\n");}void show(String a,String b){new AlertDialog.Builder(this).setTitle(a).setMessage(b).setPositiveButton("باشه",null).show();}
 @Override protected void onDestroy(){vision.stop();super.onDestroy();}
}